-- Back office work, Sales (docs/plan.md §1.124): deals for new accounts and for more from a client,
-- the people on them and their history. Operator-only tables, not a pack. New tables only, so the
-- previous Worker keeps working. Generated by drizzle-kit; the grants and row-level security at
-- the end are hand-written.
CREATE TABLE "deal" (
	"id" uuid PRIMARY KEY DEFAULT uuid_generate_v7() NOT NULL,
	"kind" text NOT NULL,
	"client_id" uuid,
	"company" text,
	"title" text NOT NULL,
	"description" text DEFAULT '' NOT NULL,
	"stage" text NOT NULL,
	"agent_count" integer DEFAULT 0 NOT NULL,
	"agents_sold" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"mrr" numeric(14, 4) DEFAULT '0' NOT NULL,
	"currency" text DEFAULT 'USD' NOT NULL,
	"outcome" text DEFAULT 'open' NOT NULL,
	"outcome_reason" text,
	"check_back_on" date,
	"waiting_on" text DEFAULT 'operator' NOT NULL,
	"status_line" text DEFAULT '' NOT NULL,
	"stuck" boolean DEFAULT false NOT NULL,
	"next_step" text DEFAULT '' NOT NULL,
	"next_due_on" date,
	"source" text DEFAULT 'ops' NOT NULL,
	"source_detail" text,
	"evidence" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"origin_kind" text,
	"origin_id" uuid,
	"agreed_mrr" numeric(14, 4),
	"agreed_from" date,
	"signed_copy_key" text,
	"signed_copy_name" text,
	"reply_tag" text,
	"dedupe_key" text,
	"created_by" uuid,
	"stage_at" timestamp with time zone DEFAULT now() NOT NULL,
	"won_at" timestamp with time zone,
	"closed_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "deal_reply_tag_key" UNIQUE("reply_tag"),
	CONSTRAINT "deal_kind_check" CHECK ("deal"."kind" in ('new', 'expansion')),
	CONSTRAINT "deal_stage_check" CHECK (("deal"."kind" = 'new' and "deal"."stage" in ('lead', 'qualified', 'diagnostic', 'proposal', 'setup', 'live')) or ("deal"."kind" = 'expansion' and "deal"."stage" in ('spotted', 'pitch', 'offered', 'agreed', 'billed'))),
	CONSTRAINT "deal_company_check" CHECK ("deal"."company" is null or char_length("deal"."company") between 1 and 200),
	CONSTRAINT "deal_title_check" CHECK (char_length("deal"."title") between 1 and 200),
	CONSTRAINT "deal_description_check" CHECK (char_length("deal"."description") <= 2000),
	CONSTRAINT "deal_agent_count_check" CHECK ("deal"."agent_count" >= 0),
	CONSTRAINT "deal_outcome_check" CHECK ("deal"."outcome" in ('open', 'won', 'lost', 'not_now', 'no')),
	CONSTRAINT "deal_waiting_on_check" CHECK ("deal"."waiting_on" in ('operator', 'reggie', 'client')),
	CONSTRAINT "deal_status_line_check" CHECK (char_length("deal"."status_line") <= 120),
	CONSTRAINT "deal_source_check" CHECK ("deal"."source" in ('site_form', 'email', 'referral', 'ops', 'reggie')),
	CONSTRAINT "deal_origin_kind_check" CHECK ("deal"."origin_kind" is null or "deal"."origin_kind" in ('deal', 'ask', 'enhancement', 'issue')),
	CONSTRAINT "deal_origin_check" CHECK (("deal"."origin_kind" is null) = ("deal"."origin_id" is null)),
	CONSTRAINT "deal_expansion_client_check" CHECK ("deal"."kind" <> 'expansion' or "deal"."client_id" is not null),
	CONSTRAINT "deal_who_check" CHECK ("deal"."client_id" is not null or "deal"."company" is not null)
);
