CREATE POLICY operator_only ON deal FOR ALL TO PUBLIC
  USING (app_is_operator() AND (client_id IS NULL OR client_id = any(app_tenant_ids())))
  WITH CHECK (app_is_operator() AND (client_id IS NULL OR client_id = any(app_tenant_ids())));
